    "guide_title": "📖 User Guide",
    "guide_sub": "How to master WA Bot Dashboard",
    "guide_h1": "1. Accounts & Limits",
    "guide_p1": "Link WhatsApp accounts via \"Linked Devices\". Set a <b>Daily Limit</b> for each account to prevent spam blocks.<br><br><b>Proxy & IP Rotation:</b> Assign Proxies (http://user:pass@ip:port) to each account to prevent mass-banning. Use <b>Rotate All IPs</b> to randomize.",
    "guide_h2": "2. Contacts & Groups",
    "guide_p2": "Go to the Contacts tab to upload a CSV/Excel file. You can also extract members from Groups using the Groups Tab. The system automatically filters out invalid numbers and <b>Removes Duplicate Numbers</b> so you never message the same person twice.",
    "guide_h3": "3. Campaigns, Files & Forwarding",
    "guide_p3": "Blast messages with attachments. Add multiple templates; the bot randomly picks one per recipient. You can attach files (Images, Videos, PDFs, etc.) directly to your campaign. Alternatively, you can use the <b>Forward Catalog</b> to seamlessly forward existing media messages directly from your WhatsApp to the recipients.",
    "guide_h4": "4. Anti-Ban Strategies",
    "guide_p4": "Set a <b>Message Delay (e.g., 5-10s)</b> between each message. Use the <b>Batch/Recipients</b> setting to pause sending after a certain number of messages (e.g., Sleep for 60 seconds after every 50 messages). This highly simulates natural human behavior.",
    "guide_h5": "5. Group Extraction Settings",
    "guide_p5": "You can select any WhatsApp group your accounts are in and extract all its members' phone numbers. When extracting numbers from groups, you can choose to <b>Exclude Group Admins</b> to avoid messaging group owners, significantly reducing the chances of your number being reported as spam.",
    "guide_h6": "6. Delay & Recipients/Batch (Anti-Ban)",
    "guide_p6": "Under Batching Settings, set a safe <b>Message Delay (e.g. 5-10 seconds)</b> between each message. Use the <b>Batch/Recipients</b> setting to pause sending after a certain number of messages.",
    "guide_h7": "7. Number Extraction & Group Selection",
    "guide_p7": "You can select any WhatsApp group your accounts are in and extract all its members' phone numbers.",
    "guide_h8": "8. Number Filtering & Removing Duplicates",
    "guide_p8": "Whenever you import numbers from files or groups, the system automatically filters out invalid numbers and duplicate numbers.",
    "guide_h9": "9. Exclude Group Admins",
    "guide_p9": "When extracting numbers from groups or sending campaigns, you can choose to ignore/remove Group Admins.",
    "guide_h10": "7. Message Scheduling",
    "guide_p10": "You can set a future date and time for your campaigns. The bot will automatically start sending messages at the scheduled time.",
    "guide_h11": "8. WhatsApp Polls",
    "guide_p11": "Engage with your audience by sending interactive Polls. You can create multiple options.",
    "guide_h12": "9. Analytics & Revoking Messages",
    "guide_p12": "The Reports Tab saves a history of all your sent campaigns. You can use Revoke Messages to delete sent messages for everyone.",

