    "guide_title": "📖 官方操作与防封指南",
    "guide_sub": "如何高效安全地玩转 WA Bot 营销系统",
    "guide_h1": "1. 账号管理与配额",
    "guide_p1": "通过 WhatsApp 的“关联设备”扫码绑定账号。务必为每个账号设置<b>每日发送上限</b>，防止触发滥用风控。<br><br><b>代理与 IP 轮换：</b> 为每个账号分配独立的代理（http://user:pass@ip:port），防止因关联导致多账号连锁封号。点击<b>更换所有 IP</b>随机重置。",
    "guide_h2": "2. 联系人与群组客户沉淀",
    "guide_p2": "上传 CSV/Excel 文件或从群组提取成员。系统会自动剔除非法号码并<b>自动去除重复号码</b>，确保绝不重复打扰同一位客户。",
    "guide_h3": "3. 营销文案、多媒体与免重复上传",
    "guide_p3": "支持发送带附件的富媒体消息。可添加多个消息模板，系统将为每位客户随机轮换文案。利用<b>转发目录</b>可实现云端秒级直发。",
    "guide_h4": "4. 核心防封控策略",
    "guide_p4": "建议在批次设置中配置 <b>5-10 秒的随机延迟</b>，并开启<b>分批冷却休眠</b>（如每发送 50 条消息休眠 60 秒），最大程度模拟真实自然人沟通习惯。",
    "guide_h5": "5. 群组号码提取与精准避险",
    "guide_p5": "可提取所在群聊的全部群友号码。提取或发送时，建议勾选<b>排除群管理员</b>，避免引起群主反感并被恶意举报投诉。",
    "guide_h6": "6. 间隔与分批策略（防封要点）",
    "guide_p6": "在批次设置中配置合理的间隔时间和休眠策略，保障账号长期稳定可用。",
    "guide_h7": "7. 号码提取与群组筛选",
    "guide_p7": "挑选账号加入的目标 WhatsApp 群组，一键导出所有群成员手机号码。",
    "guide_h8": "8. 号码过滤与去重机制",
    "guide_p8": "导入时系统会自动验证格式合规性，并自动消除重复号码。",
    "guide_h9": "9. 智能排除群主与管理人员",
    "guide_p9": "避免向群管理发送营销信息，大幅降低账号被举报的概率。",
    "guide_h10": "7. Message Scheduling",
    "guide_p10": "You can set a future date and time for your campaigns. The bot will automatically start sending messages at the scheduled time.",
    "guide_h11": "8. WhatsApp Polls",
    "guide_p11": "Engage with your audience by sending interactive Polls. You can create multiple options.",
    "guide_h12": "9. Analytics & Revoking Messages",
    "guide_p12": "The Reports Tab saves a history of all your sent campaigns. You can use Revoke Messages to delete sent messages for everyone.",

