    "guide_title": "📖 ユーザーガイド",
    "guide_sub": "WA Botダッシュボードの活用方法",
    "guide_h1": "1. アカウント管理と制限",
    "guide_p1": "「リンクされた機器」からQRコードで連携します。スパム対策として各アカウントに<b>1日の送信上限</b>を設定してください。<br><br><b>プロキシ & IPローテーション：</b> アカウントごとに個別プロキシを割り当て、大量BANを防ぎます。",
    "guide_h2": "2. 連絡先とグループ管理",
    "guide_p2": "CSVやExcelをアップロード、またはグループから抽出します。無効な番号は自動で除外され、<b>重複番号も自動削除</b>されます。",
    "guide_h3": "3. キャンペーンとメディア送信",
    "guide_p3": "画像やPDF付きメッセージを一斉送信できます。複数テンプレートを登録して文章をランダム変化させられます。<b>転送カタログ</b>も活用可能です。",
    "guide_h4": "4. BAN対策戦略",
    "guide_p4": "メッセージ間に<b>5〜10秒の遅延</b>を設定し、<b>バッチ設定</b>で一定数ごとに待機時間を設けて人間らしい送信を再現します。",
    "guide_h5": "5. グループ抽出と安全策",
    "guide_p5": "所属グループからメンバー番号を抽出できます。スパム通報を避けるため<b>管理者の除外</b>が推奨されます。",
    "guide_h6": "6. 遅延とバッチ（BAN対策）",
    "guide_p6": "安全な間隔と定期的な休憩時間を設定してください。",
    "guide_h7": "7. 電話番号の抽出",
    "guide_p7": "参加しているグループからメンバー番号を一括抽出します。",
    "guide_h8": "8. 番号のフィルタリングと重複排除",
    "guide_p8": "インポート時に無効な番号や重複番号を自動的に取り除きます。",
    "guide_h9": "9. グループ管理者の除外",
    "guide_p9": "管理者への送信を避けることで通報リスクを大幅に低減します。",
    "guide_h10": "7. Message Scheduling",
    "guide_p10": "You can set a future date and time for your campaigns. The bot will automatically start sending messages at the scheduled time.",
    "guide_h11": "8. WhatsApp Polls",
    "guide_p11": "Engage with your audience by sending interactive Polls. You can create multiple options.",
    "guide_h12": "9. Analytics & Revoking Messages",
    "guide_p12": "The Reports Tab saves a history of all your sent campaigns. You can use Revoke Messages to delete sent messages for everyone.",

