    "guide_h3": "3. 캠페인 및 미디어 전송",
    "guide_p3": "첨부 파일과 함께 대량 메시지를 발송하세요. 여러 템플릿을 등록하여 텍스트를 무작위로 변경 발송할 수 있습니다.",
    "guide_h4": "4. 차단 방지 핵심 전략",
    "guide_p4": "메시지 간 <b>5~10초 지연</b>을 설정하고, <b>배치 전송</b>을 통해 일정 건수 발송 후 주기적인 휴식 시간을 부여하세요.",
    "guide_h5": "5. 그룹 번호 추출",
    "guide_p5": "그룹에서 번호를 추출할 때 <b>그룹 관리자 제외</b>를 체크하여 스팸 신고 위험을 대폭 낮추세요.",
    "guide_h6": "6. 지연 및 배치 (차단 방지)",
    "guide_p6": "안전한 메시지 지연 시간과 배치 휴식을 설정하세요.",
    "guide_h7": "7. 번호 추출",
    "guide_p7": "참여 중인 그룹에서 멤버 번호를 한 번에 추출합니다.",
    "guide_h8": "8. 번호 필터링 및 중복 제거",
    "guide_p8": "가져오기 시 잘못된 번호와 중복 번호가 자동으로 걸러집니다.",
