    "free_tier_limit": "निःशुल्क स्तर 1 खाते की अनुमति देता है",
    "guide_title": "📖 उपयोगकर्ता मार्गदर्शिका",
    "guide_sub": "WA Bot डैशबोर्ड का प्रभावी उपयोग कैसे करें",
    "guide_h1": "1. खाता प्रबंधन",
    "guide_p1": "«लिंक्ड डिवाइसेज» के माध्यम से खातों को लिंक करें। स्पैम ब्लॉक से बचने के लिए <b>दैनिक सीमा</b> सेट करें।<br><br><b>प्रॉक्सी और आईपी रोटेशन:</b> खातों पर बैन से बचने के लिए अलग प्रॉक्सी असाइन करें।",
    "guide_h2": "2. संपर्क और समूह",
    "guide_p2": "CSV/Excel फ़ाइल अपलोड करें या ग्रुप से नंबर निकालें। सिस्टम अमान्य नंबरों को फ़िल्टर करता है और <b>डुप्लिकेट नंबरों को स्वतः हटा देता है</b>।",
    "guide_h3": "3. अभियान और मीडिया फ़ॉरवर्डिंग",
    "guide_p3": "अनुलग्नकों के साथ संदेश भेजें। संदेशों में विविधता लाने के लिए कई टेम्पलेट्स जोड़ें। <b>फ़ॉरवर्ड कैटलॉग</b> का भी उपयोग करें।",
    "guide_h4": "4. एंटी-बैन रणनीतियाँ",
    "guide_p4": "प्रत्येक संदेश के बीच <b>5-10 सेकंड का विलंब</b> सेट करें। नियमित अंतराल के लिए <b>बैचिंग सेटिंग्स</b> का उपयोग करें।",
    "guide_h5": "5. समूह निष्कर्षण",
    "guide_p5": "समूहों से नंबर निकालते समय <b>ग्रुप एडमिन को बाहर रखें</b> ताकि स्पैम रिपोर्टिंग का जोखिम न रहे।",
    "guide_h6": "6. विलंब और बैचिंग (एंटी-बैन)",
    "guide_p6": "सुरक्षित संदेश अंतराल और बैच विराम कॉन्फ़िगर करें।",
    "guide_h7": "7. नंबर निष्कर्षण",
    "guide_p7": "समूहों से सदस्यों के फ़ोन नंबर निकालें।",
    "guide_h8": "8. नंबर फ़िल्टरिंग और डुप्लिकेट हटाना",
    "guide_p8": "अमान्य और दोहराए गए नंबर स्वतः हटा दिए जाते हैं।",
    "guide_h9": "9. ग्रुप एडमिन को बाहर रखें",
    "guide_p9": "खाते की सुरक्षा के लिए ग्रुप एडमिन को संदेश न भेजें।",
    "guide_h10": "7. Message Scheduling",
    "guide_p10": "You can set a future date and time for your campaigns. The bot will automatically start sending messages at the scheduled time.",
    "guide_h11": "8. WhatsApp Polls",
    "guide_p11": "Engage with your audience by sending interactive Polls. You can create multiple options.",
    "guide_h12": "9. Analytics & Revoking Messages",
    "guide_p12": "The Reports Tab saves a history of all your sent campaigns. You can use Revoke Messages to delete sent messages for everyone.",

