    "guide_title": "📖 คู่มือการใช้งาน",
    "guide_sub": "วิธีใช้งาน WA Bot Dashboard อย่างมีประสิทธิภาพ",
    "guide_h1": "1. การจัดการบัญชี",
    "guide_p1": "เชื่อมต่อบัญชีผ่าน «อุปกรณ์ที่เชื่อมโยง» กำหนด <b>ขีดจำกัดรายวัน</b> เพื่อป้องกันการถูกระงับ<br><br><b>พร็อกซีและการหมุนเวียน IP:</b> กำหนดพร็อกซีเฉพาะเพื่อป้องกันการถูกแบนยกชุด",
    "guide_h2": "2. รายชื่อและกลุ่ม",
    "guide_p2": "อัปโหลดไฟล์ CSV/Excel หรือดึงสมาชิกกลุ่ม ระบบจะกรองเบอร์ที่ไม่ถูกต้องและ <b>ลบเบอร์ที่ซ้ำโดยอัตโนมัติ</b>",
    "guide_h3": "3. แคมเปญและสื่อ",
    "guide_p3": "ส่งข้อความพร้อมแนบไฟล์ เพิ่มหลายเทมเพลตเพื่อสุ่มข้อความ หรือใช้ <b>แคตตาล็อกส่งต่อ</b>",
    "guide_h4": "4. กลยุทธ์ป้องกันการแบน",
    "guide_p4": "ตั้ง <b>การหน่วงเวลา (5-10 วินาที)</b> ระหว่างข้อความ และใช้ <b>การตั้งค่ากลุ่ม</b> เพื่อหยุดพักเป็นระยะ",
    "guide_h5": "5. การดึงสมาชิกกลุ่มอย่างปลอดภัย",
    "guide_p5": "ดึงเบอร์จากกลุ่มและเลือก <b>แยกผู้ดูแลกลุ่มออก</b> เพื่อลดความเสี่ยงจากการถูกรายงานสแปม",
    "guide_h6": "6. การหน่วงเวลาและการแบ่งกลุ่ม (ป้องกันการแบน)",
    "guide_p6": "ตั้งค่าระยะเวลาการหน่วงเวลาและการพักกลุ่มส่งอย่างปลอดภัย",
    "guide_h7": "7. การดึงเบอร์โทรศัพท์",
    "guide_p7": "ดึงเบอร์สมาชิกจากกลุ่ม WhatsApp ที่เข้าร่วม",
    "guide_h8": "8. การกรองและคัดแยกเบอร์ซ้ำ",
    "guide_p8": "ระบบจะตัดเบอร์ที่ไม่ถูกต้องและซ้ำซ้อนออกให้อัตโนมัติ",
    "guide_h9": "9. คัดแยกผู้ดูแลกลุ่มออก",
    "guide_p9": "หลีกเลี่ยงการส่งหาผู้ดูแลกลุ่มเพื่อลดความเสี่ยงที่เบอร์จะถูกรายงาน",
    "guide_h10": "7. Message Scheduling",
    "guide_p10": "You can set a future date and time for your campaigns. The bot will automatically start sending messages at the scheduled time.",
    "guide_h11": "8. WhatsApp Polls",
    "guide_p11": "Engage with your audience by sending interactive Polls. You can create multiple options.",
    "guide_h12": "9. Analytics & Revoking Messages",
    "guide_p12": "The Reports Tab saves a history of all your sent campaigns. You can use Revoke Messages to delete sent messages for everyone.",

