    "guide_sub": "WA Bot ড্যাশবোর্ড ব্যবহারের সঠিক নিয়ম",
    "guide_h1": "১. অ্যাকাউন্ট ব্যবস্থাপনা",
    "guide_p1": "«লিঙ্কড ডিভাইসেস» দিয়ে অ্যাকাউন্ট লিঙ্ক করুন। স্প্যাম প্রতিরোধে <b>দৈনিক সীমা</b> নির্ধারণ করুন।<br><br><b>প্রক্সি ও আইপি রোটেশন:</b> ব্যান এড়াতে প্রতিটি অ্যাকাউন্টে আলাদা প্রক্সি দিন।",
    "guide_h2": "২. পরিচিতি ও গ্রুপ",
    "guide_p2": "CSV/Excel ফাইল আপলোড করুন অথবা গ্রুপ থেকে নম্বর সংগ্রহ করুন। সিস্টেম ভুল নম্বর এবং <b>ডুপ্লিকেট নম্বর স্বয়ংক্রিয়ভাবে মুছে ফেলে</b>।",
    "guide_h3": "৩. ক্যাম্পেইন ও মিডিয়া",
    "guide_p3": "ফাইল সহ বার্তা পাঠান। বার্তার বৈচিত্র্যের জন্য একাধিক টেমপ্লেট ব্যবহার করুন।",
    "guide_h4": "৪. অ্যান্টি-ব্যান কৌশল",
    "guide_p4": "প্রতি বার্তার মাঝে <b>৫-১০ সেকেন্ড বিলম্ব</b> দিন এবং <b>ব্যাচ সেটিংস</b> ব্যবহার করে বিরতি দিন।",
    "guide_h5": "৫. গ্রুপ নম্বর সংগ্রহ",
    "guide_p5": "গ্রুপ থেকে নম্বর সংগ্রহের সময় <b>গ্রুপ অ্যাডমিনদের বাদ দিন</b> যাতে স্প্যাম রিপোর্ট না হয়।",
    "guide_h6": "৬. বিলম্ব এবং ব্যাচিং",
    "guide_p6": "নিরাপদ বার্তা বিরতি কনফিগার করুন।",
    "guide_h7": "৭. নম্বর নিষ্কাশন",
    "guide_p7": "গ্রুপ থেকে সদস্য নম্বর বের করুন।",
    "guide_h8": "৮. নম্বর ফিল্টারিং",
