    "upgrade_to_pro": "இந்த அம்சத்தைத் திறக்க PRO க்கு மேம்படுத்தவும்.",
    "btn_upgrade_now": "இப்போதே மேம்படுத்து",
    "free_tier_limit": "இலவச பதிப்பில் 1 கணக்கு மட்டுமே அனுமதிக்கப்படுகிறது",
    "guide_title": "📖 பயனர் கையேடு",
    "guide_sub": "WA Bot டாஷ்போர்டை எவ்வாறு சரியாகப் பயன்படுத்துவது",
    "guide_h1": "1. கணக்கு மேலாண்மை",
    "guide_p1": "«இணைக்கப்பட்ட சாதனங்கள்» மூலம் கணக்குகளை இணைக்கவும். தடைகளைத் தவிர்க்க <b>தினசரி வரம்பை</b> அமைக்கவும்.<br><br><b>ப்ராக்ஸி & IP சுழற்சி:</b> கணக்குகள் முடக்கப்படுவதைத் தவிர்க்க ப்ராக்ஸிகளைப் பயன்படுத்தவும்.",
    "guide_h2": "2. தொடர்புகள் மற்றும் குழுக்கள்",
    "guide_p2": "CSV/Excel கோப்புகளைப் பதிவேற்றவும். தவறான எண்கள் தானாகவே வடிகட்டப்பட்டு <b>போலி எண்கள் நீக்கப்படும்</b>.",
    "guide_h3": "3. பிரச்சாரங்கள் மற்றும் மீடியா",
    "guide_p3": "கோப்புகளுடன் செய்திகளை அனுப்புங்கள். பல டெம்ப்ளேட்டுகளைப் பயன்படுத்தி உரையை மாற்றவும்.",
    "guide_h4": "4. தடை பாதுகாப்பு உத்திகள்",
    "guide_p4": "ஒவ்வொரு செய்திக்கும் இடையே <b>5-10 விநாடிகள் தாமதத்தை</b> அமைக்கவும். தொகுதி அமைப்புகளைப் பயன்படுத்தி இடைவெளி விடவும்.",
    "guide_h5": "5. குழு எண்களைப் பிரித்தெடுத்தல்",
    "guide_p5": "குழுக்களிலிருந்து எண்களை எடுக்கும்போது <b>குழு நிர்வாகிகளைத் தவிர்க்கவும்</b>.",
    "guide_h6": "6. தாமதம் மற்றும் தொகுதிகள்",
