window.translations = translations;

function applyTranslations(lang) {
  if (!translations[lang]) return;
  const t = translations[lang];
  const fallback = translations['en'] || {};

  function getTranslation(key) {
    if (t && t[key] !== undefined && t[key] !== '') return t[key];
    if (fallback && fallback[key] !== undefined && fallback[key] !== '') return fallback[key];
    return null;
  }

  // 1. Elements with data-i18n
  document.querySelectorAll("[data-i18n]").forEach(el => {
    const key = el.getAttribute("data-i18n");
    const val = getTranslation(key);
    if (val !== null && val !== undefined) {
      if ((el.tagName === "INPUT" || el.tagName === "TEXTAREA") && el.hasAttribute("placeholder")) {
        el.setAttribute("placeholder", val);
      } else if (el.tagName === "INPUT" && (el.type === "button" || el.type === "submit")) {
        el.value = val;
      } else {
        // If element contains <i> or <svg> and translation text doesn't contain HTML icon tags, preserve the icon
        const icon = el.querySelector("i, svg");
        if (icon && !val.includes("<i") && !val.includes("<svg")) {
          const isIconFirst = el.firstElementChild === icon || (el.childNodes[0] && el.childNodes[0].contains && el.childNodes[0].contains(icon));
          if (isIconFirst) {
            el.innerHTML = icon.outerHTML + " " + val;
          } else {
            el.innerHTML = val + " " + icon.outerHTML;
          }
        } else {
          el.innerHTML = val;
        }
      }
    }
  });

  // 2. Elements with data-i18n-placeholder
  document.querySelectorAll("[data-i18n-placeholder]").forEach(el => {
    const key = el.getAttribute("data-i18n-placeholder");
    const val = getTranslation(key);
    if (val !== null && val !== undefined) {
      el.setAttribute("placeholder", val);
    }
  });

  // 3. Elements with data-i18n-title
  document.querySelectorAll("[data-i18n-title]").forEach(el => {
    const key = el.getAttribute("data-i18n-title");
    const val = getTranslation(key);
    if (val !== null && val !== undefined) {
      el.setAttribute("title", val);
    }
  });

  // 4. Direction & Document Lang
  document.documentElement.lang = lang;
  if (lang === 'ar' || lang === 'ur') {
    document.documentElement.dir = 'rtl';
  } else {
    document.documentElement.dir = 'ltr';
  }

  // 5. Store in localStorage
  localStorage.setItem("app_lang", lang);

  // 6. Update #page-title if present
  const activeNav = document.querySelector(".nav-item.active");
  const pageTitle = document.getElementById("page-title");
  if (activeNav && pageTitle) {
    const tid = activeNav.getAttribute("data-tab");
    const tabMap = {
      'tab-accounts': 'title_accounts',
      'tab-contacts': 'title_contacts',
      'tab-templates': 'title_templates',
      'tab-campaign': 'title_campaign',
      'tab-groups': 'title_groups',
      'tab-reports': 'title_reports',
      'tab-settings': 'title_settings'
    };
    const titleKey = tabMap[tid] || pageTitle.getAttribute("data-i18n");
    if (titleKey) {
      pageTitle.setAttribute("data-i18n", titleKey);
      const translatedTitle = getTranslation(titleKey);
      if (translatedTitle) pageTitle.textContent = translatedTitle;
    }
  }
}

window.applyTranslations = applyTranslations;

const langSwitcher = document.getElementById("lang-switcher");
if (langSwitcher) {
  const savedLang = localStorage.getItem("app_lang") || "en";
  langSwitcher.value = savedLang;
  applyTranslations(savedLang);

  langSwitcher.addEventListener("change", (e) => {
    applyTranslations(e.target.value);
  });
}
